#include <zephyr/toolchain.h>
#include <zephyr/linker/sections.h>
#include <zephyr/sys/util.h>
#include <zephyr/sys/iterable_sections.h>
#include <zephyr/ztest_assert.h>
#include <zephyr/ztest_test_deprecated.h>

#ifdef __cplusplus
extern "C" {
#endif

struct ztest_test_node {
	const char *name;
	void (*test_fn)(void);
};

struct ztest_suite_node {
	const char *name;
	struct ztest_test_node *test_cases;
	size_t test_cases_count;
	void (*setup)(void);
	void (*teardown)(void);
	void (*before)(void);
	void (*after)(void);
};

typedef void (*ztest_suite_setup_fn)(void);
typedef void (*ztest_suite_teardown_fn)(void);
typedef void (*ztest_suite_before_fn)(void);
typedef void (*ztest_suite_after_fn)(void);

/* Helper macros to extract setup/teardown/before/after functions from __VA_ARGS__ */
/* ZTEST_SUITE(name, setup_fn, teardown_fn, before_fn, after_fn) */
/* The __VA_ARGS__ can be:
 * - empty (no setup/teardown/before/after)
 * - setup_fn, teardown_fn
 * - setup_fn, teardown_fn, before_fn
 * - setup_fn, teardown_fn, before_fn, after_fn
 */

/* Macros to define the weak setup/teardown/before/after functions for a suite. */
/* These functions will call the user-provided functions if they exist, or do nothing. */
#define Z_ZTEST_SUITE_SETUP_ARGS_0()
#define Z_ZTEST_SUITE_SETUP_ARGS_2(setup_fn, teardown_fn) setup_fn()
#define Z_ZTEST_SUITE_SETUP_ARGS_3(setup_fn, teardown_fn, before_fn) setup_fn()
#define Z_ZTEST_SUITE_SETUP_ARGS_4(setup_fn, teardown_fn, before_fn, after_fn) setup_fn()

#define Z_ZTEST_SUITE_TEARDOWN_ARGS_0()
#define Z_ZTEST_SUITE_TEARDOWN_ARGS_2(setup_fn, teardown_fn) teardown_fn()
#define Z_ZTEST_SUITE_TEARDOWN_ARGS_3(setup_fn, teardown_fn, before_fn) teardown_fn()
#define Z_ZTEST_SUITE_TEARDOWN_ARGS_4(setup_fn, teardown_fn, before_fn, after_fn) teardown_fn()

#define Z_ZTEST_SUITE_BEFORE_ARGS_0()
#define Z_ZTEST_SUITE_BEFORE_ARGS_2(setup_fn, teardown_fn)
#define Z_ZTEST_SUITE_BEFORE_ARGS_3(setup_fn, teardown_fn, before_fn) before_fn()
#define Z_ZTEST_SUITE_BEFORE_ARGS_4(setup_fn, teardown_fn, before_fn, after_fn) before_fn()

#define Z_ZTEST_SUITE_AFTER_ARGS_0()
#define Z_ZTEST_SUITE_AFTER_ARGS_2(setup_fn, teardown_fn)
#define Z_ZTEST_SUITE_AFTER_ARGS_3(setup_fn, teardown_fn, before_fn)
#define Z_ZTEST_SUITE_AFTER_ARGS_4(setup_fn, teardown_fn, before_fn, after_fn) after_fn()

#define Z_ZTEST_SUITE_SETUP_CALL(...) \
	_CONCAT(Z_ZTEST_SUITE_SETUP_ARGS_, NUM_VA_ARGS(__VA_ARGS__))(__VA_ARGS__)

#define Z_ZTEST_SUITE_TEARDOWN_CALL(...) \
	_CONCAT(Z_ZTEST_SUITE_TEARDOWN_ARGS_, NUM_VA_ARGS(__VA_ARGS__))(__VA_ARGS__)

#define Z_ZTEST_SUITE_BEFORE_CALL(...) \
	_CONCAT(Z_ZTEST_SUITE_BEFORE_ARGS_, NUM_VA_ARGS(__VA_ARGS__))(__VA_ARGS__)

#define Z_ZTEST_SUITE_AFTER_CALL(...) \
	_CONCAT(Z_ZTEST_SUITE_AFTER_ARGS_, NUM_VA_ARGS(__VA_ARGS__))(__VA_ARGS__)

/* These macros are used inside ZTEST_SUITE_DEFINE_SETUP_TEARDOWN */
#define Z_ZTEST_SUITE_SETUP_##name(...) Z_ZTEST_SUITE_SETUP_CALL(__VA_ARGS__)
#define Z_ZTEST_SUITE_TEARDOWN_##name(...) Z_ZTEST_SUITE_TEARDOWN_CALL(__VA_ARGS__)
#define Z_ZTEST_SUITE_BEFORE_##name(...) Z_ZTEST_SUITE_BEFORE_CALL(__VA_ARGS__)
#define Z_ZTEST_SUITE_AFTER_##name(...) Z_ZTEST_SUITE_AFTER_CALL(__VA_ARGS__)

#define ZTEST_SUITE_DEFINE_SETUP_TEARDOWN(name, ...) \
	static void ztest_suite_setup_##name(void) __attribute__((weak)); \
	static void ztest_suite_setup_##name(void) { \
		Z_ZTEST_SUITE_SETUP_##name(__VA_ARGS__); \
	} \
	static void ztest_suite_teardown_##name(void) __attribute__((weak)); \
	static void ztest_suite_teardown_##name(void) { \
		Z_ZTEST_SUITE_TEARDOWN_##name(__VA_ARGS__); \
	} \
	static void ztest_suite_before_##name(void) __attribute__((weak)); \
	static void ztest_suite_before_##name(void) { \
		Z_ZTEST_SUITE_BEFORE_##name(__VA_ARGS__); \
	} \
	static void ztest_suite_after_##name(void) __attribute__((weak)); \
	static void ztest_suite_after_##name(void) { \
		Z_ZTEST_SUITE_AFTER_##name(__VA_ARGS__); \
	}

#define ZTEST_SUITE(name, ...) \
	static struct ztest_test_node __attribute__((__used__)) \
	__section(".ztest_tests_" #name) __ztest_test_cases_##name[] = { \
		/* This array is populated by ZTEST_TEST macros */ \
	}; \
	static struct ztest_suite_node __attribute__((__used__)) \
	_CONCAT(__ztest_suite_, name) = { \
		.name = #name, \
		.test_cases = __ztest_test_cases_##name, \
		.test_cases_count = ARRAY_SIZE(__ztest_test_cases_##name), \
		.setup = (ztest_suite_setup_fn)ztest_suite_setup_##name, \
		.teardown = (ztest_suite_teardown_fn)ztest_suite_teardown_##name, \
		.before = (ztest_suite_before_fn)ztest_suite_before_##name, \
		.after = (ztest_suite_after_fn)ztest_suite_after_##name, \
	}; \
	ZTEST_SUITE_DEFINE_SETUP_TEARDOWN(name, __VA_ARGS__)

#define ZTEST_TEST(suite_name, test_name) \
	static void test_name(void); \
	static struct ztest_test_node __attribute__((__used__)) \
	_CONCAT(__ztest_test_, suite_name ## _ ## test_name) \
	__section(".ztest_tests_" #suite_name) = { \
		.name = #test_name, \
		.test_fn = test_name, \
	}; \
	static void test_name(void)

#define ZTEST_F(suite_name, test_name) \
	static void test_name(void); \
	static struct ztest_test_node __attribute__((__used__)) \
	_CONCAT(__ztest_test_, suite_name ## _ ## test_name) \
	__section(".ztest_tests_" #suite_name) = { \
		.name = #test_name, \
		.test_fn = test_name, \
	}; \
	static void test_name(void)

#define ZTEST_DMEM_TEST(suite_name, test_name) \
	static void test_name(void); \
	static struct ztest_test_node __attribute__((__used__)) \
	_CONCAT(__ztest_test_, suite_name ## _ ## test_name) \
	__section(".ztest_tests_" #suite_name) = { \
		.name = #test_name, \
		.test_fn = test_name, \
	}; \
	static void test_name(void)

#define ZTEST_BMEM_TEST(suite_name, test_name) \
	static void test_name(void); \
	static struct ztest_test_node __attribute__((__used__)) \
	_CONCAT(__ztest_test_, suite_name ## _ ## test_name) \
	__section(".ztest_tests_" #suite_name) = { \
		.name = #test_name, \
		.test_fn = test_name, \
	}; \
	static void test_name(void)

#define ZTEST_PMEM_TEST(suite_name, test_name) \
	static void test_name(void); \
	static struct ztest_test_node __attribute__((__used__)) \
	_CONCAT(__ztest_test_, suite_name ## _ ## test_name) \
	__section(".ztest_tests_" #suite_name) = { \
		.name = #test_name, \
		.test_fn = test_name, \
	}; \
	static void test_name(void)

#define ZTEST_SUITE_REGISTER(name) \
	STRUCT_SECTION_ITERABLE(ztest_suite_node, _CONCAT(__ztest_suite_, name))

#ifdef __cplusplus
}
#endif
